// Content with portions generated by generative AI platform
package org.eclipse.kura.core.test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.KuraConnectException;
import org.eclipse.kura.data.DataTransportService;
import org.eclipse.kura.util.wire.test.WireTestUtil;
import org.junit.After;
import org.junit.Test;

public class WebSocketIdleConnectionTest extends BaseCloudTests {

    private static final String BROKER_ADDR_WS = "ws://localhost:8080";
    private static final String UNREACHABLE_BROKER_ADDR_WS = "ws://localhost:8089";
    private static final String TEST_MQTT_DATA_TRANSPORT_PID = "testWebSocketIdle";
    private static final String MQTT_DATA_TRANSPORT_FACTORY_PID = "org.eclipse.kura.core.data.transport.mqtt.MqttDataTransport";
    private static final long IDLE_PERIOD_MS = 5000;

    private DataTransportService transport;
    private KuraConnectException connectException;

    @Test
    public void connectionOverWebSocketSurvivesIdlePeriod() throws Exception {
        givenMqttDataTransportWithBrokerUrl(BROKER_ADDR_WS);
        givenTransportConnected();

        whenNoTrafficFor(IDLE_PERIOD_MS);

        thenTransportIsConnected();
    }

    @Test
    public void connectionOverWebSocketFailsWithUnreachableBroker() throws Exception {
        givenMqttDataTransportWithBrokerUrl(UNREACHABLE_BROKER_ADDR_WS);

        whenTransportConnects();

        thenConnectionFails();
    }

    @After
    public void cleanup() throws Exception {
        if (this.transport != null) {
            if (this.transport.isConnected()) {
                this.transport.disconnect(0);
            }
            WireTestUtil.deleteFactoryConfiguration(configurationService, TEST_MQTT_DATA_TRANSPORT_PID).get(30,
                    TimeUnit.SECONDS);
        }
    }

    private void givenMqttDataTransportWithBrokerUrl(final String brokerUrl) throws Exception {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("broker-url", brokerUrl);
        properties.put("username", "mqtt");
        properties.put("password", "bar");

        this.transport = WireTestUtil.createFactoryConfiguration(configurationService, DataTransportService.class,
                TEST_MQTT_DATA_TRANSPORT_PID, MQTT_DATA_TRANSPORT_FACTORY_PID, properties).get(30, TimeUnit.SECONDS);
    }

    private void givenTransportConnected() throws KuraConnectException {
        this.transport.connect();
        assertTrue(this.transport.isConnected());
    }

    private void whenNoTrafficFor(final long millis) throws InterruptedException {
        Thread.sleep(millis);
    }

    private void whenTransportConnects() {
        try {
            this.transport.connect();
        } catch (final KuraConnectException e) {
            this.connectException = e;
        }
    }

    private void thenTransportIsConnected() {
        assertTrue(this.transport.isConnected());
    }

    private void thenConnectionFails() {
        assertNotNull(this.connectException);
        assertFalse(this.transport.isConnected());
    }
}
